#!/usr/bin/env bash
# v4 통 일러스트 2종 생성 (Codex image_gen). 참조: refs/1_layout.png(v3 구도), refs/2_spirit.png(정령 디자인), refs/3_harvester.png
cd "$(dirname "$0")/../../.." || exit 1
D=Marketing/thumbnails_2026-10-20/v4; R=$D/refs
COMMON="itch.io game cover illustration, LANDSCAPE 1.26:1 (e.g. 1536x1218). Repaint reference 1 as ONE single cohesive watercolor painting, keeping its composition almost exactly: TOP-LEFT area (left 50%, top 33%) stays calm simple sky/canopy wash with nothing in it (the title logo will be placed there later). Left and center: a lush patch of red white-spotted mushrooms and golden chanterelles; a cream motion trail sweeps from the lower-left corner to the center where the round wooden harvester disc (reference 3: round wooden disc, wooden knob and handle, curved silver crescent blade) is spinning mid-swing, slicing through the patch, leaving cut white stumps. Cut mushroom caps, leaves and a burst of about a dozen round gold coins (each with a small square hole, like old cash coins) fly up and to the right from the harvester. RIGHT side (x 70%-95%, lower 60%): the mushroom spirit from reference 2 — big coral-red cap with cream spots, round cream body, tiny dark dot eyes wide open in surprise, small pink blush, little stubby arms raised, brown feet — standing on the grass, startled and leaning back slightly, about 40% of the image height, painted into the scene with the same light and a soft cast shadow. Keep the character design exactly like reference 2 (simple dot eyes, no big shiny anime eyes, no mouth detail beyond a tiny one). Warm late-afternoon light from the upper right, deeper moss/teal shade at the edges. Reference 4 = the game's background painting style."
gen(){ node Tools/codex-image.mjs --style $D/style.md --ref $R/1_layout.png --ref $R/2_spirit.png --ref $R/3_harvester.png --ref Assets/Resources/Art/Dream/Backgrounds/bg_ranch_core.png --prompt "$COMMON $2" --out $D/$1_raw.png --timeout 540 > $D/_$1.log 2>&1; echo "EXIT $?" >> $D/_$1.log; }
gen A_num "Also paint, in the upper-middle-right just right of the empty logo area (around x 75%, y 27%), the bold number '+590K' in chunky rounded cream letters with a dark brown outline, slanted, like a game damage-number popup, plus a small '!' above the spirit's cap. Spell exactly +590K. No other text anywhere." &
gen B_clean "No text, no letters, no numbers anywhere in the image (keep the area around x 75%, y 27% as part of the scene with flying caps and coins)." &
wait
# 이후: python v4/compose.py A_num A --logo 0.50,0.03,0.035  /  python v4/compose.py B_clean B --logo 0.50,0.03,0.035
